import hashlib, itertools, json, pathlib

runs = {}
for p in sorted(pathlib.Path("runs").glob("*/meta.json")):
    d = json.loads(p.read_text())
    runs[d["run"]] = (d["mode"], d["seal"])

algos = ["md5","sha1","sha256","sha512","blake2b","blake2s","sha3_256"]
seps  = ["", ":", "|", "-", "/", "\t", " ", "_"]
prefixes = ["", "st6", "st6-", "st6:"]

def cands(run, mode):
    for s in seps:
        for pre in prefixes:
            yield pre + run + s + mode
            yield pre + mode + s + run
            yield pre + mode
            yield pre + run

hits = []
for run,(mode,seal) in runs.items():
    tail = seal.split("-",1)[1]
    for other in ("fast","safe"):
        for c in set(cands(run, other)):
            for a in algos:
                h = hashlib.new(a, c.encode()).hexdigest()
                if h.startswith(tail):
                    hits.append((run, other, a, repr(c)))
print("seal matches:", hits or "none")
